// Breadth-first traversal of the monstypes.txt equiv1/equiv2/equiv3 parent-type hierarchy to test whether monster type nMonTypeId belongs to type nCheckTypeId. Returns 1 if found, 0 if not found, out-of-range, or stack depth exceeds 124. Despite its name, behaves as a monster-type membership test (analogous to ITEMTBLS_CheckItemTypeRecursive but for MonType with three equiv slots).
BOOL MONSTERTBLS_GetMonSeqFrameCount(int32_t nMonTypeId, int32_t nCheckTypeId) {
    int nNewStackSize;
    int32_t typeStack[128];
    short int wEquiv3;
    if (nCheckTypeId < 1) {
      return 0;
    }
    if (nMonTypeId < 1 || sgtDataTable.nTxtMonTypeSize <= nMonTypeId) {
      return 0;
    }

    typeStack[0] = nMonTypeId;
    int nStackSize = 1;
    do {
      int nCurrentTypeId;
      nCurrentTypeId = typeStack[nStackSize - 1];
      nNewStackSize = nStackSize - 1;
      if (nCheckTypeId == nCurrentTypeId) {
        return 1;
      }
      if (sgtDataTable.nTxtMonTypeSize <= nCurrentTypeId) {
        return 0;
      }
      if (0x7c < nNewStackSize) {
        return 0;
      }
      if (0 < sgtDataTable.pTxtMonType[nCurrentTypeId].equiv1) {
        typeStack[nNewStackSize] = (int)sgtDataTable.pTxtMonType[nCurrentTypeId].equiv1;
        nNewStackSize = nStackSize;
        if (sgtDataTable.pTxtMonType[nCurrentTypeId].equiv2) {
          wEquiv3 = sgtDataTable.pTxtMonType[nCurrentTypeId].equiv3;
          typeStack[nStackSize] = (int)sgtDataTable.pTxtMonType[nCurrentTypeId].equiv2;
          nNewStackSize = nStackSize + 1;
          if (wEquiv3) {
            typeStack[nNewStackSize] = (int)wEquiv3;
            nNewStackSize = nStackSize + 2;
          }
        }
      }

      nStackSize = nNewStackSize;
    } while (nNewStackSize);

    return 0;
}

// Loads and compiles the montype.txt data table into sgtDataTable.pTxtMonType. Defines 7 field descriptors (type, equiv1-3, strsing, strplur, end), calls CompileTxt, then allocates and populates a bitfield matrix (nTxtMonTypeSize x ceil(nTxtMonTypeSize/32) words) encoding the transitive type-membership graph by calling MONSTERTBLS_GetMonSeqFrameCount for every (row, col) type pair.
void __fastcall TXT_AllocTxt_montype(D2PoolManagerStrc * pMemory) {
    BOOL bIsSubType;
    uint32_t nBitIdx;
    D2BinFieldInputStrc aFieldDefs[7];
    uint8_t* pBitArray;
    aFieldDefs[0].fpLinker = &sgtDataTable.pTxtMonTypeLink;
    aFieldDefs[1].eType = FIELDTYPE_NAME_SHORT;
    aFieldDefs[1].fpLinker = &sgtDataTable.pTxtMonTypeLink;
    aFieldDefs[2].eType = FIELDTYPE_NAME_SHORT;
    aFieldDefs[2].fpLinker = &sgtDataTable.pTxtMonTypeLink;
    aFieldDefs[3].eType = FIELDTYPE_NAME_SHORT;
    aFieldDefs[3].fpLinker = &sgtDataTable.pTxtMonTypeLink;
    aFieldDefs[0].szName = "type";
    aFieldDefs[0].eType = FIELDTYPE_NAME_I_WORD;
    aFieldDefs[0].nSize = 0;
    aFieldDefs[0].nOffset = 0;
    aFieldDefs[1].szName = "equiv1";
    aFieldDefs[1].nSize = 0;
    aFieldDefs[1].nOffset = 2;
    aFieldDefs[2].szName = "equiv2";
    aFieldDefs[2].nSize = 0;
    aFieldDefs[2].nOffset = 4;
    aFieldDefs[3].szName = "equiv3";
    aFieldDefs[3].nSize = 0;
    aFieldDefs[3].nOffset = 6;
    aFieldDefs[4].szName = "strsing";
    aFieldDefs[4].eType = FIELDTYPE_KEY_WORD;
    aFieldDefs[4].nSize = 0;
    aFieldDefs[4].nOffset = 8;
    aFieldDefs[4].fpLinker = (void*)DataTbls::DATATBLS_LookupStringId;
    aFieldDefs[5].szName = "strplur";
    aFieldDefs[5].eType = FIELDTYPE_KEY_WORD;
    aFieldDefs[5].nSize = 0;
    aFieldDefs[5].nOffset = 10;
    aFieldDefs[5].fpLinker = (void*)DataTbls::DATATBLS_LookupStringId;
    aFieldDefs[6].szName = "end";
    aFieldDefs[6].eType = FIELDTYPE_END;
    aFieldDefs[6].nSize = 0;
    aFieldDefs[6].nOffset = 0;
    aFieldDefs[6].fpLinker = 0;
    sgtDataTable.pTxtMonTypeLink = Fog::Src::Excel::STRUCT_CreateTxtLinkStrc(".\\DATATBLS\\MonsterTbls.cpp", 0xaf6);
    sgtDataTable.pTxtMonType = (D2MonTypeTxt*)DataTbls::CompileTxt(pMemory, "montype", aFieldDefs, &sgtDataTable.nTxtMonTypeSize, 0xc);
    sgtDataTable.nMonTypeEquivRowDwords = (int)(sgtDataTable.nTxtMonTypeSize + 0x1f + (sgtDataTable.nTxtMonTypeSize + 0x1f >> 0x1f & 0x1fU)) >> 5;
    size_t nBitMatrixBytes = sgtDataTable.nMonTypeEquivRowDwords * sgtDataTable.nTxtMonTypeSize * 4;
    sgtDataTable.pTxtMonTypeUnknown = D2_ALLOC_POOL(nullptr, nBitMatrixBytes);
    memset(sgtDataTable.pTxtMonTypeUnknown, 0, nBitMatrixBytes);
    int nRowTypeIdx = 0;
    int nMonTypeTotal = sgtDataTable.nTxtMonTypeSize;
    if (0 >= sgtDataTable.nTxtMonTypeSize) {
      return;
    }

    do {
      int nTypeIdx;
      pBitArray = (uint8_t*)sgtDataTable.pTxtMonTypeUnknown;
      nTypeIdx = nRowTypeIdx * sgtDataTable.nMonTypeEquivRowDwords;
      nBitIdx = 0;
      if (0 < nMonTypeTotal) {
        do {
          bIsSubType = MONSTERTBLS_GetMonSeqFrameCount(nRowTypeIdx, nBitIdx);
          if (bIsSubType) {
            *(uint32_t*)(pBitArray + ((int)nBitIdx >> 5) * 4 + nTypeIdx * 4) |= gadwBitMasks[nBitIdx & 0x1f];
            nMonTypeTotal = sgtDataTable.nTxtMonTypeSize;
          }

          nBitIdx++;
        } while ((int)nBitIdx < nMonTypeTotal);
      }

      nRowTypeIdx++;
    } while (nRowTypeIdx < nMonTypeTotal);
}

void __stdcall MONSTERTBLS_FreeMonPlaceTxt() {
    if (!sgtDataTable.pTxtMonType) {
      return;
    }

    DataTbls::UnloadBin(sgtDataTable.pTxtMonType);
    Fog::Src::Excel::STRUCT_FreeTxtLink(sgtDataTable.pTxtMonTypeLink);
    D2_FREE_POOL(nullptr, sgtDataTable.pTxtMonTypeUnknown);
    sgtDataTable.pTxtMonType = 0;
    sgtDataTable.pTxtMonTypeLink = 0;
}

